// Generates the files that Obsidian cannot translate at run time (Bases names, the note
// template, the statistics note) from one source plus the locale files.
//
//   node tools/build-localized.mjs           write the files
//   node tools/build-localized.mjs --check   fail if a generated file is missing or outdated
//
// Output, per language code:
//   example-vault/Colophon/localized/Library.<code>.base
//   example-vault/Colophon/localized/Book.<code>.md
//   example-vault/Colophon/localized/Statistics.<code>.md
// and the English versions are also installed as the demo vault's working files:
//   example-vault/Books/Library.base, example-vault/Templates/Book.md, example-vault/Books/Statistics.md
import fs from 'node:fs';
import path from 'node:path';
import YAML from 'yaml';
import { COLOPHON, ROOT, VAULT, loadLocales, read, rel } from './common.mjs';
import { library } from './sources/library.mjs';

const check = process.argv.includes('--check');
const locales = loadLocales();
const outputs = new Map();

const BASE_HEADER = (code) =>
  `# Generated by tools/build-localized.mjs from tools/sources/library.mjs and Colophon/locales/${code}.json. Do not edit by hand.\n`;

const render = (source, t) =>
  source.replace(/\{\{t:([\w.]+)\}\}/g, (_, key) => t(key));

for (const [code, messages] of Object.entries(locales)) {
  const t = (key) => {
    const value = messages[key] ?? locales.en[key];
    if (typeof value !== 'string') throw new Error(`${code}: "${key}" is not a plain string`);
    return value;
  };

  const base = library(t);
  const names = base.views.map((v) => v.name);
  const duplicate = names.find((n, i) => names.indexOf(n) !== i);
  if (duplicate) throw new Error(`${code}: two Library views are both called "${duplicate}"`);
  outputs.set(
    path.join(COLOPHON, 'localized', `Library.${code}.base`),
    BASE_HEADER(code) + YAML.stringify(base, { lineWidth: 0 }),
  );

  const book = render(read(path.join(ROOT, 'tools/sources/Book.md')), t);
  const statistics = render(read(path.join(ROOT, 'tools/sources/Statistics.md')), t);
  outputs.set(path.join(COLOPHON, 'localized', `Book.${code}.md`), book);
  outputs.set(path.join(COLOPHON, 'localized', `Statistics.${code}.md`), statistics);

  if (code === 'en') {
    outputs.set(path.join(VAULT, 'Books', 'Library.base'), BASE_HEADER(code) + YAML.stringify(base, { lineWidth: 0 }));
    outputs.set(path.join(VAULT, 'Templates', 'Book.md'), book);
    outputs.set(path.join(VAULT, 'Books', 'Statistics.md'), statistics);
  }
}

// Files in localized/ that no longer belong to any language are stale.
const localizedDir = path.join(COLOPHON, 'localized');
const stale = fs.existsSync(localizedDir)
  ? fs.readdirSync(localizedDir).map((f) => path.join(localizedDir, f)).filter((f) => !outputs.has(f))
  : [];

let problems = 0;
for (const [file, content] of outputs) {
  const current = fs.existsSync(file) ? read(file) : null;
  if (current === content) continue;
  if (check) {
    console.error(`error: ${rel(file)} is ${current === null ? 'missing' : 'out of date'}; run "npm run build"`);
    problems++;
  } else {
    fs.mkdirSync(path.dirname(file), { recursive: true });
    fs.writeFileSync(file, content);
    console.log(`wrote ${rel(file)}`);
  }
}
for (const file of stale) {
  if (check) {
    console.error(`error: ${rel(file)} is stale; run "npm run build"`);
    problems++;
  } else {
    fs.rmSync(file);
    console.log(`removed ${rel(file)}`);
  }
}

if (check) {
  if (problems) process.exitCode = 1;
  else console.log(`localized files: ok (${outputs.size} files)`);
}
